+for(let x=-10;x<=10;x+=.7){const wire=new THREE.Mesh(new THREE.TorusGeometry(.36,.018,4,16),steel);wire.position.set(x,4,-16.3);wire.rotation.y=Math.PI/2;scene.add(wire)}
+// Cage-light fixtures
+for(const x of [-8,0,8]){box(scene,x,5,-8,.9,.13,.25,mat(0x282625));const glow=new THREE.PointLight(0xffbd76,x===0?78:45,13,2);glow.position.set(x,4.7,-8);scene.add(glow);const bulb=new THREE.Mesh(new THREE.BoxGeometry(.7,.035,.15),new THREE.MeshBasicMaterial({color:0xffd49a}));bulb.position.set(x,4.88,-8);scene.add(bulb)}
