+for(let i=0;i<18;i++){let x=((i*37)%17)-8,z=((i*23)%23)-12;if(Math.abs(x)<2&&z>0)continue;const b=box(scene,x,.12,z,.18+((i%3)*.1),.2,.15,rust);b.rotation.y=i*1.7}
+box(scene,-7,.45,-2,2,.8,.55,mat(0x353330));box(scene,-7,1.15,-2,2.25,.12,.7,steel);
