+// Cell/gate exit detail, framed in hard yellow
+box(scene,5,1.65,14.55,.12,3,.12,yellow);box(scene,10.8,1.65,14.55,.12,3,.12,yellow);box(scene,8,3.15,14.55,5.8,.12,.12,yellow);
