+// Procedural fighter character
+function fighter(isPlayer=false){const root=new THREE.Group();scene.add(root);const skin=mat(isPlayer?0x936b52:0x9a745b),shirt=mat(isPlayer?0x292c2c:0x55403a),pants=mat(isPlayer?0x30302d:0x363438),boot=mat(0x171819),accent=isPlayer?mat(0x59604a):mat(0x63443a);
+ const torso=new THREE.Group();torso.position.y=1.12;root.add(torso);const body=new THREE.Mesh(new THREE.BoxGeometry(.7,.84,.38),shirt);body.castShadow=true;torso.add(body);
+ const vest=new THREE.Mesh(new THREE.BoxGeometry(.73,.58,.41),accent);vest.position.set(0,.01,-.015);vest.castShadow=true;torso.add(vest);
+ const head=new THREE.Mesh(new THREE.SphereGeometry(.23,12,10),skin);head.position.set(0,.64,0);head.scale.set(.86,1.1,.88);head.castShadow=true;torso.add(head);
+ const hair=new THREE.Mesh(new THREE.SphereGeometry(.235,10,7,0,Math.PI*2,0,Math.PI*.52),mat(isPlayer?0x241e1a:0x1d1b1b));hair.position.copy(head.position).add(new THREE.Vector3(0,.03,0));torso.add(hair);
