+ const leg=new THREE.Group();leg.position.set(side*.22,.72,0);root.add(leg);const thigh=new THREE.Mesh(new THREE.CylinderGeometry(.16,.19,.61,8),pants);thigh.position.y=-.3;thigh.castShadow=true;leg.add(thigh);const shoe=new THREE.Mesh(new THREE.BoxGeometry(.25,.16,.4),boot);shoe.position.set(0,-.62,-.09);shoe.castShadow=true;leg.add(shoe);limbs.push(leg)}
+ const shadow=new THREE.Mesh(new THREE.CircleGeometry(.56,20),new THREE.MeshBasicMaterial({color:0x0b0c0d,transparent:true,opacity:.38,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.008;root.add(shadow);
+ root.userData={torso,limbs,isPlayer,shirt,dead:false,hitFlash:0};return root}
+const player=fighter(true);player.position.set(0,0,4);player.rotation.y=Math.PI;
+const enemies=[];const starts=[[-2.8, -4],[2.5,-6],[-.2,-10]];
+for(let i=0;i<3;i++){const e=fighter(false);e.position.set(starts[i][0],0,starts[i][1]);e.rotation.y=0;e.userData.id=i;e.userData.hp=100;e.userData.maxHp=100;e.userData.attack=0;e.userData.stun=0;e.userData.dead=false;e.userData.walk=0;e.userData.name=['THE WALL','YARD DOG','SENTINEL'][i];enemies.push(e)}
