for(let i=0;i<3;i++){const e=fighter(false);e.position.set(starts[i][0],0,starts[i][1]);e.rotation.y=0;e.userData.id=i;e.userData.hp=100;e.userData.maxHp=100;e.userData.attack=0;e.userData.stun=0;e.userData.dead=false;e.userData.walk=0;e.userData.name=['THE WALL','YARD DOG','SENTINEL'][i];enemies.push(e)}
const keys=new Set();let active=false,ended=false,playerHp=100,stamina=100,attackCd=0,dodgeCd=0,dodgeTime=0,invuln=0,combo=0,comboTimer=0,lockIndex=0,hitStop=0,elapsed=0,kills=0;
const hpEl=document.querySelector('#health'),hpText=document.querySelector('#hptext'),stamEl=document.querySelector('#stamina'),comboEl=document.querySelector('#combocount'),enemyHud=document.querySelector('#enemyhud'),enemyHp=document.querySelector('#enemyhp'),enemyName=document.querySelector('#enemyname'),leftEl=document.querySelector('#left'),toast=document.querySelector('#toast'),hurt=document.querySelector('#hurt'),cover=document.querySelector('#cover'),objective=document.querySelector('#objective');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function alive(){return enemies.filter(e=>!e.userData.dead)}
function targetEnemy(){const live=alive();if(!live.length)return null;if(keys.has('l')){}if(lockIndex>=enemies.length||enemies[lockIndex].userData.dead)lockIndex=enemies.findIndex(e=>!e.userData.dead);return enemies[lockIndex]||live[0]}
function showToast(title,sub='',dur=1.1){toast.innerHTML=`<div class="big">${title}</div><div class="sub">${sub}</div>`;clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.innerHTML='',dur*1000)}
function startGame(){if(active)return;active=true;cover.classList.add('hide');document.querySelector('#hint').style.opacity='1';showToast('STAY UP.','THE GATE IS THE ONLY WAY OUT.',1.8)}
document.querySelector('#start').addEventListener('click',startGame);
function hurtPlayer(damage){if(invuln>0||ended)return;playerHp=Math.max(0,playerHp-damage);invuln=.48;player.userData.hitFlash=.18;hitStop=.045;hurt.classList.add('on');setTimeout(()=>hurt.classList.remove('on'),110);if(playerHp<=0){finish(false);return}showToast('','',.1);}
function impact(enemy,damage,heavy){enemy.userData.hp=Math.max(0,enemy.userData.hp-damage);enemy.userData.stun=heavy?.65:.34;enemy.userData.hitFlash=.19;hitStop=.065;const dx=enemy.position.x-player.position.x,dz=enemy.position.z-player.position.z,dist=Math.hypot(dx,dz)||1;enemy.position.x+=dx/dist*(heavy?.9:.48);enemy.position.z+=dz/dist*(heavy?.9:.48);
 if(comboTimer>0)combo++;else combo=1;comboTimer=1.35;comboEl.textContent=`COMBO × ${combo}`;
 for(let i=0;i<7;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.025,5,4),new THREE.MeshBasicMaterial({color:i%2?0xd4c09a:0xa43e31}));p.position.set(enemy.position.x+(Math.random()-.5)*.6,1.15+Math.random()*.8,enemy.position.z+(Math.random()-.5)*.5);scene.add(p);p.userData.life=.35+Math.random()*.25;p.userData.vel=new THREE.Vector3((Math.random()-.5)*2,Math.random()*2,(Math.random()-.5)*2);effects.push(p)}
 if(enemy.userData.hp<=0){enemy.userData.dead=true;enemy.userData.death=0;kills++;leftEl.textContent=alive().length;showToast(['DOWN.','NICE WORK.','ONE LESS.'][Math.floor(Math.random()*3)],`${alive().length} HOSTILES REMAIN`,1);if(!alive().length)setTimeout(()=>finish(true),750)}
 updateHUD()}
const effects=[];
function updateHUD(){hpEl.style.width=`${playerHp}%`;hpText.textContent=`${Math.ceil(playerHp)} / 100`;stamEl.style.width=`${stamina}%`;hpEl.style.background=playerHp<30?'#ef483a':'#d8ff3e';const t=targetEnemy();if(t&&!t.userData.dead){enemyHud.classList.add('show');enemyName.textContent=`${t.userData.name} // ${Math.ceil(t.userData.hp)}%`;enemyHp.style.width=`${t.userData.hp}%`}else enemyHud.classList.remove('show')}
function strike(heavy=false){if(!active||ended||attackCd>0)return;if(heavy&&stamina<28){showToast('WIND GONE.','WAIT A BEAT.',.6);return}attackCd=heavy?.72:.38;if(heavy)stamina-=28;const t=targetEnemy();player.userData.swing=.3;player.userData.heavy=heavy;let hit=false;if(t){const dx=t.position.x-player.position.x,dz=t.position.z-player.position.z,dist=Math.hypot(dx,dz)||1,forwardX=Math.sin(player.rotation.y),forwardZ=Math.cos(player.rotation.y),dot=(dx/dist)*forwardX+(dz/dist)*forwardZ;if(dist<(heavy?2.45:1.9)&&dot>-.08){impact(t,heavy?42:19,heavy);hit=true}}
 if(!hit&&Math.random()<.32)showToast(heavy?'MISS.':'', '',.3);}
function dodge(){if(!active||ended||dodgeCd>0||stamina<22)return;stamina-=22;dodgeCd=.75;dodgeTime=.23;invuln=.35;player.userData.dodge=.23;}
function finish(win){if(ended)return;ended=true;active=false;document.querySelector('#hint').style.opacity='0';objective.innerHTML=win?'<span>EXIT //</span> THE GATE IS OPEN':'<span>END OF THE LINE //</span> SUBJECT 09 DOWN';setTimeout(()=>{cover.classList.remove('hide');const c=document.querySelector('.covercontent');c.querySelector('.eyebrow').textContent=win?'SECTOR C — EXIT SECURED':'SECTOR C — SUBJECT DOWN';c.querySelector('h1').innerHTML=win?'MADE IT<br><em>OUT.</em>':'NOT<br><em>YET.</em>';c.querySelector('.lead').textContent=win?`You cleared the yard with ${Math.ceil(playerHp)}% condition. The night shift is over. For now.`:'The yard took its toll. Get back up and take another shot at the gate.';c.querySelector('#start').textContent=win?'Run it again ↗':'Get back up ↗';c.querySelector('#start').onclick=()=>location.reload();},950)}
function onKey(e,down){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(down){keys.add(k);if(k==='j')strike(false);if(k==='k')strike(true);if(k===' ')dodge();if(k==='l'&&active){let next=(lockIndex+1)%enemies.length;while(enemies[next].userData.dead&&next!==lockIndex)next=(next+1)%enemies.length;lockIndex=next;updateHUD()}}else keys.delete(k)}
window.addEventListener('keydown',e=>onKey(e,true));window.addEventListener('keyup',e=>onKey(e,false));
document.querySelectorAll('.mobile button').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(k==='j')strike();else if(k==='k')strike(true);else if(k==='space')dodge();else if(k==='l'){lockIndex=(lockIndex+1)%enemies.length;updateHUD()}else keys.add(k)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(k)))});

